-- ----------------------------
-- Table structure for Verify
-- ----------------------------
DROP TABLE IF EXISTS "Verify" CASCADE;
CREATE TABLE "Verify" (
  "id" NUMBER(20) NOT NULL,
  "type" NUMBER(11) NOT NULL,
  "phone" NUMBER(20) NOT NULL,
  "verify" NUMBER(11) NOT NULL,
  "date" DATE NOT NULL
)
;
COMMENT ON COLUMN "Verify"."id" IS '唯一标识';
COMMENT ON COLUMN "Verify"."type" IS '类型：
0-登录
1-注册
2-修改登录密码
3-修改支付密码';
COMMENT ON COLUMN "Verify"."phone" IS '手机号';
COMMENT ON COLUMN "Verify"."verify" IS '验证码';
COMMENT ON COLUMN "Verify"."date" IS '创建时间';

